solution.Solution.cs:
public static class Solution
{
    public static bool IsLeapYear(int year)
    {
        return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    }

    public static string Clock(int minutes)
    {
        int m = ((minutes % 1440) + 1440) % 1440;
        return $"{m / 60}:{m % 60:D2}";
    }

    public static int Change(int cents, int coin)
    {
        return cents / coin;
    }

    public static bool CanVote(int age, bool isCitizen, bool isRegistered)
    {
        return age >= 18 && isCitizen && isRegistered;
    }
}

unitTests:
Test("leap years", () =>
{
    CheckEq(IsLeapYear(2024), true);
    CheckEq(IsLeapYear(2023), false);
    CheckEq(IsLeapYear(1900), false);
    CheckEq(IsLeapYear(2000), true);
});

Test("clock times", () =>
{
    CheckEq(Clock(125), "2:05");
    CheckEq(Clock(0), "0:00");
    CheckEq(Clock(1439), "23:59");
    CheckEq(Clock(1440), "0:00");
    CheckEq(Clock(-30), "23:30");
    CheckEq(Clock(3000), "2:00");
});

Test("coins", () =>
{
    CheckEq(Change(185, 50), 3);
    CheckEq(Change(49, 50), 0);
    CheckEq(Change(100, 25), 4);
});

Test("voting", () =>
{
    CheckEq(CanVote(18, true, true), true);
    CheckEq(CanVote(17, true, true), false);
    CheckEq(CanVote(30, false, true), false);
    CheckEq(CanVote(30, true, false), false);
});

